import{_ as o,o as s,c as a,ae as t}from"./chunks/framework.YL6nI5ZP.js";const u=JSON.parse('{"title":"How to Deploy Local SWMM","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/05-deploy.md","filePath":"how-to/05-deploy.md"}'),l={name:"how-to/05-deploy.md"};function i(d,e,r,c,n,p){return s(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="how-to-deploy-local-swmm" tabindex="-1">How to Deploy Local SWMM <a class="header-anchor" href="#how-to-deploy-local-swmm" aria-label="Permalink to &quot;How to Deploy Local SWMM&quot;">​</a></h1><p>Deploy the app to a static host. The production site is <a href="https://swmm6.is-local.org" target="_blank" rel="noreferrer">https://swmm6.is-local.org</a> (Cloudflare Pages); a GitHub Pages workflow also exists.</p><p>The 2D engine wasm is built with <strong>pthreads/OpenMP</strong> (<code>scripts/build-openswmm2d.sh</code> / <code>.ps1</code>), so it needs <strong>cross-origin isolation</strong> — <code>SharedArrayBuffer</code> is only available to pages served with <code>Cross-Origin-Opener-Policy</code> + <code>Cross-Origin-Embedder-Policy</code>. GitHub Pages does not allow custom headers and cannot serve the threaded build. <strong>Use Cloudflare Pages.</strong></p><h2 id="_1-deploy-via-cloudflare-pages-recommended" tabindex="-1">1. Deploy via Cloudflare Pages (recommended) <a class="header-anchor" href="#_1-deploy-via-cloudflare-pages-recommended" aria-label="Permalink to &quot;1. Deploy via Cloudflare Pages (recommended)&quot;">​</a></h2><p>Deploys happen from <code>.github/workflows/cloudflare.yml</code> on push to <code>main</code> / <code>experimental</code> (the workflow also lists <code>website</code>). It writes <code>config.js</code> and <code>build-version.js</code> (cache stamp) from secrets, then uploads <code>public/</code> via <code>cloudflare/pages-action</code>.</p><p>Setup (once):</p><ol><li>Create a Pages project (or run <code>npx wrangler pages deploy public</code> manually — <code>wrangler.toml</code> is provided).</li><li>Add repository secrets: <ul><li><code>CLOUDFLARE_API_TOKEN</code> (a token with <code>Pages:Edit</code> permission)</li><li><code>CLOUDFLARE_ACCOUNT_ID</code></li><li><code>CLOUDFLARE_PROJECT_NAME</code></li><li>the existing <code>MAPBOX_ACCESS_TOKEN</code>, <code>GOOGLE_MAPS_API_KEY</code>, <code>OPENTOPOGRAPHY_API_KEY</code></li></ul></li><li>Point your custom domain (<code>swmm6.is-local.org</code>) at the Pages project. The <code>Cross-Origin-Opener-Policy: same-origin</code> / <code>Cross-Origin-Embedder-Policy: credentialless</code> headers come from <code>public/_headers</code> (credentialless so Mapbox/Google/OpenTopography resources load without CORP headers).</li><li>Delete <code>.github/workflows/static.yml</code> (GitHub Pages) once Cloudflare is live.</li></ol><p><code>wrangler.toml</code> (provided in the repo root) lets you push manually:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pages</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public</span></span></code></pre></div><h2 id="_2-deploy-via-github-pages-github-workflows-static-yml" tabindex="-1">2. Deploy via GitHub Pages (<code>.github/workflows/static.yml</code>) <a class="header-anchor" href="#_2-deploy-via-github-pages-github-workflows-static-yml" aria-label="Permalink to &quot;2. Deploy via GitHub Pages (`.github/workflows/static.yml`)&quot;">​</a></h2><p><strong>GitHub Pages deploy only — there is no WASM build in CI.</strong> The engine is built locally on <code>experimental</code> and the artifacts are committed to <code>public/</code>.</p><p>The workflow does:</p><ol><li>Triggers: push to <code>main</code> + <code>experimental</code>, or manual dispatch.</li><li>Checkout (v4, no <code>submodules: recursive</code> — prebuilt wasm ships in <code>public/</code>).</li><li><strong>Generate <code>public/config.js</code> from secrets</strong> (<code>MAPBOX_ACCESS_TOKEN</code>, <code>GOOGLE_MAPS_API_KEY</code>, <code>OPENTOPOGRAPHY_API_KEY</code>).</li><li>Upload <code>./public</code> as a Pages artifact → deploy with <code>actions/deploy-pages@v4</code>.</li></ol><blockquote><p>Note (from the workflow file): GitHub Pages cannot set COOP/COEP headers, so the threaded 2D wasm (pthreads/SharedArrayBuffer) will <strong>NOT</strong> run on this deployment. Remove this workflow once Cloudflare is live.</p></blockquote><h2 id="_3-serve-locally-for-development" tabindex="-1">3. Serve locally for development <a class="header-anchor" href="#_3-serve-locally-for-development" aria-label="Permalink to &quot;3. Serve locally for development&quot;">​</a></h2><p><code>python server.py</code> sends the same COOP/COEP headers, so the threaded engine works on <code>http://127.0.0.1:8080</code> out of the box. The server binds <code>127.0.0.1</code> only, serves <code>&lt;repo&gt;/public</code> on port <strong>8080</strong>, exposes <code>GET /api/status</code> (→ <code>{&quot;status&quot;:&quot;running&quot;,&quot;msg&quot;:&quot;3D Map Prototype Server Online&quot;}</code>), and sends <code>Cache-Control: no-store</code> plus <code>Access-Control-Allow-Origin: *</code> on OPTIONS + <code>/api/status</code>. Scripts auto-spawn it when <code>http://127.0.0.1:8080/api/status</code> is unreachable.</p>',16)])])}const g=o(l,[["render",i]]);export{u as __pageData,g as default};
